-- One-time invitation links (A6 D4). Only the SHA-256 of a link's token is stored. A member link is
-- generated by an owner and may name a squad; an owner link comes from the admin-invite command
-- alone, so it has no creator and no squad.
CREATE TABLE v2_invite_links (
	id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
	token_hash bytea NOT NULL UNIQUE,
	tenant_id  uuid NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
	role       text NOT NULL CHECK (role IN ('member', 'owner')),
	squad_id   uuid REFERENCES v2_squads (id),
	created_by uuid REFERENCES users (id),
	created_at timestamptz NOT NULL DEFAULT now(),
	expires_at timestamptz NOT NULL,
	revoked_at timestamptz,
	used_by    uuid REFERENCES users (id),
	used_at    timestamptz,
	CHECK ((used_by IS NULL) = (used_at IS NULL)),
	CHECK (role = 'member' OR (created_by IS NULL AND squad_id IS NULL)),
	CHECK (role = 'owner' OR created_by IS NOT NULL)
);
CREATE INDEX v2_invite_links_tenant ON v2_invite_links (tenant_id, created_at);
